package com.smartdeploy.controller; import com.smartdeploy.model.ServiceRequest; import com.smartdeploy.service.DockerService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/services") @CrossOrigin public class ServiceController {private final DockerService d; public ServiceController(DockerService d){this.d=d;} @GetMapping public List<String> list(){return d.list();} @PostMapping public Map<String,String> add(@Valid @RequestBody ServiceRequest r){return Map.of("message",d.add(r));} @PostMapping("/{name}/start") public Map<String,String> start(@PathVariable String name){return Map.of("message",d.start(name));} @PostMapping("/{name}/stop") public Map<String,String> stop(@PathVariable String name){return Map.of("message",d.stop(name));} @PostMapping("/{name}/restart") public Map<String,String> restart(@PathVariable String name){return Map.of("message",d.restart(name));} @DeleteMapping("/{name}") public Map<String,String> remove(@PathVariable String name){return Map.of("message",d.remove(name));} @GetMapping("/docker-version") public Map<String,String> version(){return Map.of("version",d.version());}}